-- =============================================================================
-- MySQL 8.x Schema & Seed Data for Revenue Estimation System (FY 2571)
-- Charset: utf8mb4 / Collation: utf8mb4_unicode_ci (Thai Support)
-- =============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `profiles` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `email` VARCHAR(191) NOT NULL UNIQUE,
  `full_name` VARCHAR(255) NOT NULL,
  `role` ENUM('SUPER_ADMIN','PLANNING_OFFICER','FINANCE_OFFICER','EXECUTIVE','PROJECT_OWNER','EVALUATOR') NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `audit_logs` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `table_name` VARCHAR(100) NOT NULL,
  `record_id` CHAR(36) NOT NULL,
  `action` ENUM('INSERT','UPDATE','SOFT_DELETE','DELETE','APPROVE','UNLOCK') NOT NULL,
  `old_data` JSON NULL,
  `new_data` JSON NULL,
  `performed_by` CHAR(36) NULL,
  `performed_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_audit_table_record` (`table_name`, `record_id`),
  INDEX `idx_audit_performed_by` (`performed_by`),
  INDEX `idx_audit_performed_at` (`performed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fiscal_years` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `be_year` INT NOT NULL UNIQUE,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `estimate_versions` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `fiscal_year_id` CHAR(36) NOT NULL,
  `version_no` INT NOT NULL,
  `label` VARCHAR(255) NOT NULL,
  `status` ENUM('draft','submitted','approved','locked') NOT NULL DEFAULT 'draft',
  `parent_version_id` CHAR(36) NULL,
  `approved_by` CHAR(36) NULL,
  `approved_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_fy_version` (`fiscal_year_id`, `version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `parameters` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NULL,
  `key` VARCHAR(100) NOT NULL,
  `value_numeric` DECIMAL(14,4) NULL,
  `value_text` VARCHAR(500) NULL,
  `effective_be_year` INT NOT NULL,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `month_distribution` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `month_seq` TINYINT NOT NULL,
  `semester` TINYINT NOT NULL,
  `pct` DECIMAL(10,6) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_ver_sem_month` (`version_id`, `semester`, `month_seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `rounding_rules` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NULL,
  `scope` VARCHAR(100) NOT NULL,
  `mode` ENUM('trunc','round','floor','none') NOT NULL,
  `digits` INT NOT NULL DEFAULT -3,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `programs` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `code` VARCHAR(50) NOT NULL UNIQUE,
  `name_th` VARCHAR(255) NOT NULL,
  `level` ENUM('bachelor','master','doctoral') NOT NULL,
  `report_group` ENUM('1.1.1','1.1.2','1.1.3','1.1.4','1.1.5','1.1.6','1.1.7') NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `fee_schedules` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `level` ENUM('bachelor','master','doctoral') NOT NULL,
  `library_fee` DECIMAL(14,2) NOT NULL,
  `it_fee` DECIMAL(14,2) NOT NULL,
  `health_fee` DECIMAL(14,2) NOT NULL,
  `registration_fee` DECIMAL(14,2) NOT NULL,
  `total_deduction_per_head` DECIMAL(14,2) NOT NULL,
  `library_refund_pct` DECIMAL(10,6) NOT NULL,
  `effective_be_year` INT NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_level_year` (`level`, `effective_be_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tuition_lines` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `program_id` CHAR(36) NOT NULL,
  `cohort_code` VARCHAR(20) NULL,
  `line_type` ENUM('regular','gen_ed_in','gen_ed_out') NOT NULL,
  `headcount_sem2` INT NOT NULL DEFAULT 0,
  `headcount_sem1` INT NOT NULL DEFAULT 0,
  `fee_per_head` DECIMAL(14,2) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `service_projects` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `name` VARCHAR(500) NOT NULL,
  `partner` VARCHAR(255) NULL,
  `category` ENUM('short_course','usac','le','school_activity') NOT NULL,
  `batches` INT NOT NULL DEFAULT 1,
  `attendees_per_batch` INT NOT NULL DEFAULT 0,
  `fee_per_head` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `apply_mgmt_deduction` TINYINT(1) NOT NULL DEFAULT 1,
  `month_seq` TINYINT NOT NULL,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `research_projects` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `name` TEXT NOT NULL,
  `funder` VARCHAR(255) NULL,
  `pi_name` VARCHAR(255) NULL,
  `budget` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `overhead_rate_override` DECIMAL(10,6) NULL,
  `month_seq` TINYINT NOT NULL,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `rental_items` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `tenant` VARCHAR(255) NULL,
  `area_sqm` DECIMAL(10,2) NULL,
  `monthly_rent` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `start_month_seq` TINYINT NOT NULL,
  `end_month_seq` TINYINT NOT NULL,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `carryover` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL UNIQUE,
  `amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `source_note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `other_income_lines` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `month_seq` TINYINT NOT NULL,
  `gross` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `deduction` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `revenue_actuals` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `fiscal_year_id` CHAR(36) NOT NULL,
  `received_date` DATE NULL,
  `month_seq` TINYINT NOT NULL,
  `revenue_type` ENUM('TUITION','ACAD_SERVICE','RESEARCH_OH','RENT','CARRYOVER','OTHER') NOT NULL,
  `source_name` VARCHAR(255) NOT NULL,
  `ref_no` VARCHAR(100) NULL,
  `gross` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `deduction` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `net` DECIMAL(14,2) GENERATED ALWAYS AS (`gross` - `deduction`) STORED,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `expenditure_actuals` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `fiscal_year_id` CHAR(36) NOT NULL,
  `month_seq` TINYINT NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL DEFAULT 0,
  `note` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_fy_exp_month` (`fiscal_year_id`, `month_seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `allocation_dimensions` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `code` ENUM('plan','expense_category','strategic') NOT NULL UNIQUE,
  `name_th` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `allocation_items` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `dimension_id` CHAR(36) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_dim_item_name` (`dimension_id`, `name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `allocation_pcts` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL,
  `item_id` CHAR(36) NOT NULL,
  `revenue_type` ENUM('TUITION','ACAD_SERVICE','RESEARCH_OH','RENT','CARRYOVER','OTHER') NOT NULL,
  `pct` DECIMAL(10,6) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_ver_item_revtype` (`version_id`, `item_id`, `revenue_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `historical_usage` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `item_id` CHAR(36) NOT NULL,
  `be_year` INT NOT NULL,
  `amount` DECIMAL(14,2) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL,
  UNIQUE KEY `uq_item_hist_year` (`item_id`, `be_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `version_snapshots` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NOT NULL UNIQUE,
  `payload` JSON NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `private_files` (
  `id` CHAR(36) NOT NULL PRIMARY KEY,
  `version_id` CHAR(36) NULL,
  `original_name` VARCHAR(255) NOT NULL,
  `disk_path` VARCHAR(500) NOT NULL,
  `mime_type` VARCHAR(150) NOT NULL,
  `size_bytes` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `category` VARCHAR(50) NOT NULL DEFAULT 'excel_export',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` CHAR(36) NULL,
  `deleted_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

